\begin{align*}
\frac{|H_{p_k}(\le n)|}{|S_{p_k}(\le n)|}
&\le \frac{\sum_{r=1}^{o(1)\log_{p_k}{n}}\Psi(n/p_k^r,p_{k-1})}{\sum_{r=1}^{\log_{p_k}{n}}\Psi(n/p_k^r,p_{k-1})} 
&= \frac{O(\log{n}\log^{k-2}{n})+\sum_{r=1}^{o(1)\log_{p_k}{n}}\log^{k-1}{n/p_k^r}}{O(\log{n}\log^{k-2}{n})+\sum_{r=1}^{\log_{p_k}{n}}\log^{k-1}{n/p_k^r}} 
&= \frac{O(\log{n}\log^{k-2}{n})+\sum_{r=1}^{o(1)\log_{p_k}{n}}\log^{k-1}{n}}{O(\log{n}\log^{k-2}{n})+\sum_{r=1}^{\log_{p_k}{n}}\log^{k-1}{n}} 
