	\begin{align*} 
	&m\left(\left\{x\in A_y: p(x_1,x_2,x_3,x_4)=y \text{ and }y \text{ is extremal among } \{x_i : 1\le i\le 4 \} \right\}\right)=
	&=4y^3+4(1-y)^3.
&m\left(\left\{x\in A_y: p(x_1,x_2,x_3,x_4)=y \text{ and }y \text{ is not extremal among } \{x_i : 1\le i\le 4 \} \right\}\right)=
&=4- 4y^3-4(1-y)^3.
\end{align*}
